npx --yes --package @playwright/cli playwright-cli eval "() => { const btns = Array.from(document.querySelectorAll('.btn-row .btn')); const out = []; btns.forEach((b, i) => { const chain = []; let n = b; while (n && n !== document.body) { const r = n.getBoundingClientRect(); const cs = getComputedStyle(n); chain.push(n.tagName + '|' + String(n.className && n.className.baseVal !== undefined ? n.className.baseVal : n.className).slice(0,60) + '|l=' + Math.round(r.left) + '|w=' + Math.round(r.width)); n = n.parentElement; } out.push('BTN' + i + ': ' + b.textContent.trim().slice(0,25) + ' r=' + Math.round(b.getBoundingClientRect().right) + ' :: ' + chain.join(' < ')); }); return out.join(' ||| '); }" > $null 2>&1
